with d as (select value r from jsonb_array_elements($q$[{"notes":["Make the patties up to 4 hours ahead and keep in the fridge; cook them just before serving.","The dipping sauce keeps in a jar in the fridge for a week, good for leftovers too.","Swap the herbs around depending on what's growing; mint and coriander are the core two, but thai basil and Vietnamese mint both work.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"Make the dipping sauce first: whisk together fish sauce, sugar, lime juice, garlic, chilli if using, and warm water in a small bowl until the sugar dissolves. Taste and adjust the balance of salty, sour and sweet, it should be sharp and punchy. Set aside."},{"text":"Put the pork mince in a bowl with garlic, fish sauce, sugar, salt and pepper. Mix gently with your hands until just combined, don't overwork it or the patties will be tough. Divide into 8 portions and shape each into a flat oval patty about 1.5 cm thick."},{"text":"Heat a grill pan or barbecue hotplate over medium-high heat. Brush with oil, then cook the patties 3 to 4 minutes on each side, until cooked through (no pink inside) and charred at the edges. Transfer to a plate."},{"text":"While the pork cooks, bring a pot of water to the boil and cook the rice vermicelli according to packet instructions until soft and tender. Drain and rinse with cold water to stop it cooking."},{"text":"Arrange the lettuce, mint, coriander, thai basil if using, cucumber and noodles on a platter. Place the warm pork patties on top and scatter over the crushed peanuts."},{"text":"Serve with the dipping sauce on the side, each person tears some herbs and lettuce, takes a bite of pork, and dips it all into the sauce."}],"id":"acf2dd4e-1d50-4640-8b43-1212d301d953"},{"notes":["The pâté keeps in a sealed jar in the fridge for up to 4 days.","If you can find it, a layer of clarified butter poured over the top helps preserve it and keeps the surface from darkening.","A small glass of cold white wine or a squeeze of fresh lemon on the side is lovely.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Bring a small pot of salted water to a gentle simmer. Add the cod livers and poach for 4–5 minutes, until they turn pale and opaque. Skim any foam from the surface. Drain well and let cool slightly."},{"text":"In a mortar and pestle or small food processor, crush or pulse the warm cod livers with the softened butter until completely smooth and creamy, this should take 2–3 minutes."},{"text":"Fold in the minced shallot, Dijon mustard and red wine vinegar, stirring until just combined. Taste and season with salt and pepper."},{"text":"Press the pâté through a fine-mesh sieve into a serving bowl or small jar, pushing gently with the back of a spoon to create a silky texture. Alternatively, leave it chunky if you prefer."},{"text":"Cover and chill for at least 30 minutes before serving. Serve on warm buttered toast or crackers."}],"id":"df79d1d8-fdbb-4fe3-8109-6e5dce9d35de"},{"notes":["Make a big batch and freeze half. It keeps well and tastes even better reheated.","Goat meat works just as well, some say better. If using goat, cook for a bit longer, maybe 2 hours.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"steps":[{"text":"Heat the oil in a large pot over medium-high heat. Add the meat and brown on all sides, about 8 minutes. Remove and set aside."},{"text":"In the same pot, add the onion halves, whole chillies, crushed garlic and ginger. Stir for 2 minutes until fragrant."},{"text":"Add the tomato paste, cayenne and black pepper. Stir well for 1 minute to coat the meat."},{"text":"Return the meat to the pot. Add the crushed stock cubes and water. Bring to a boil, then reduce to a simmer until the broth is fragrant and the meat is tender."},{"text":"Cover and cook for 1 to 1.5 hours, until the meat is very tender and the broth is rich and deeply flavoured. Stir occasionally."},{"text":"Remove the onion halves and whole chillies (or leave them in if you like more heat). Taste and season with salt."},{"text":"Serve hot in bowls, with a piece of meat and plenty of the spiced broth."}],"id":"a56305b5-f5f2-4b63-a87c-c1890308be4e"},{"notes":["Serve with roti, steamed rice or just with flatbread to soak up the sauce.","This curry is best eaten the day you make it, but keeps in the fridge for 2 days. Reheat gently so the fish doesn't toughen.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Heat the oil in a heavy pot over medium heat. Add the sliced onion and cook, stirring occasionally, until soft and golden, about 8 minutes."},{"text":"Add the garlic and ginger, and stir until fragrant, about 2 minutes."},{"text":"Add the turmeric, fenugreek seeds and cumin seeds, stirring constantly for 1 minute to bloom the spices."},{"text":"Pour in the coconut milk and water, and stir well to combine. Bring to a gentle simmer until the sauce is steaming and lightly bubbling at the edges."},{"text":"Add the fish pieces and salt. Simmer gently, uncovered, for 12–15 minutes until the fish is cooked through and flakes easily with a fork. Don't stir aggressively or the fish will break apart."},{"text":"Taste and adjust the salt. Add lime juice to brighten the flavour. Serve hot with roti or rice, scattered with fresh coriander if you like."}],"id":"d4f8b86d-c692-4dbe-bc04-51ababa45b61"},{"notes":["Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Pat the fish dry and season both sides generously with salt and pepper."},{"text":"Heat the oil in a large frying pan over medium-high heat. Once shimmering, place the fish skin-side down and cook without moving for 4–5 minutes, until the skin is crispy and golden. Flip gently and cook for a further 2–3 minutes until just cooked through. Transfer to a warm plate."},{"text":"Return the pan to medium heat and add the butter. Let it melt, then keep cooking, swirling often, until it turns golden and smells nutty, about 2–3 minutes. Watch it, it can burn quickly."},{"text":"Add the capers to the butter and cook for 30 seconds, until they sizzle, split open and the butter smells nutty and turns golden brown. Remove from heat and stir in the lemon juice."},{"text":"Pour the burnt butter and capers over the fish. Scatter with parsley if you like, and serve straight away."}],"id":"0bd9278a-0438-4e31-8e9d-01a9306acf41"},{"notes":["Injera keeps for a few days wrapped in a clean cloth at room temperature, or refrigerated for up to a week. Reheat gently in a covered pan.","The fermentation time is essential, don't rush it. The sour flavour and spongy texture both come from the three days of fermentation.","For the best results, use a proper injera pan (a shallow, wide non-stick pan) or a large non-stick crepe pan. A regular frying pan works but the edges can be harder to achieve."],"steps":[{"text":"Mix the teff flour with about 375 ml of water and salt in a large bowl, stirring well to combine. The batter should be thick but pourable, similar to pancake batter. Add more water a little at a time if needed."},{"text":"Cover the bowl loosely with a clean cloth and leave at room temperature for 3 days. Stir the batter once or twice a day. You'll see bubbles form and smell a pleasant sourness develop, this is the fermentation happening."},{"text":"On the third day, stir the batter well. It should be slightly thinner and bubbly. If it seems too thick, add a little warm water and stir until it reaches the consistency of a thin pancake batter."},{"text":"Heat a large non-stick frying pan or injera pan (or crepe pan) over medium-high heat. You want it very hot but not smoking. Don't oil the pan."},{"text":"Once hot, pour about 150 ml of batter into the centre of the pan and immediately tilt and rotate the pan so the batter spreads out evenly to the edges, just like making a large, thin crêpe."},{"text":"Cook for 2 to 3 minutes. The top will bubble and steam holes will form. You're looking for the bread to be cooked through but still pale, it shouldn't brown. The edges will lift slightly when it's ready."},{"text":"Slide the injera onto a large plate once the surface is covered in small holes and the edges are just lifting and set. The spongy side (top) will have absorbed the steam and created the holes that make it perfect for scooping. Repeat with the remaining batter."},{"text":"Stack the finished injera on a plate to keep warm. Serve immediately with your favourite stews and dishes."}],"id":"e2ce1361-4d7f-4324-a17b-18007b160456"},{"notes":["If you don't have a gas hob, skip the nori toasting, the rolls will still taste great untoasted.","Make ahead: assemble and slice the rolls up to 2 hours before serving; keep wrapped in cling film in the fridge."],"id":"b3a865c6-163e-486e-bff6-b466182e1e13"},{"notes":["The dough can be made ahead and refrigerated overnight; let it come to room temperature before stretching.","If your roti doesn't stretch thin enough, let it rest for a minute and try again, don't force it or it'll tear.","Dal curry keeps in the fridge for up to 3 days and reheats gently over low heat."],"steps":[{"text":"Make the dough: mix flour and salt in a large bowl. Slowly add warm water while stirring, then add 2 tbsp oil. Mix until shaggy, then knead for 8–10 minutes by hand until smooth and elastic. Cover with damp cloth and rest for 20 minutes."},{"text":"Meanwhile, make the dal curry: heat oil in a pan, fry onion until golden, about 5 minutes. Add garlic and ginger, cook for 1 minute. Add turmeric, cumin and chilli powder, cook for 30 seconds until fragrant."},{"text":"Rinse lentils and add to the pan with coconut milk and 200 ml water. Bring to simmer and cook, stirring occasionally, until lentils break down and curry thickens, about 15–20 minutes. Season with salt to taste."},{"text":"Divide dough into 4 equal balls. Lightly oil a bench top. Take one ball and press flat, then stretch it out slowly with your hands, working from the edge, until thin enough to almost see through, about 30 cm across. Don't worry if it tears."},{"text":"Fold the stretched dough into a square or triangle shape, tucking in the edges to create layers. Flatten gently with your palms until it's about 1 cm thick."},{"text":"Heat a non-stick pan or griddle over medium-high heat with a little oil. Cook each roti for 2–3 minutes on each side, pressing gently with a spatula, until golden and puffed with crispy edges. Transfer to a plate and cover with a clean cloth to keep warm."},{"text":"Serve roti warm, torn into pieces, alongside the hot dal curry for dipping."}],"id":"b00ad2d2-453a-4cb6-a5b1-e211313fb009"},{"notes":["If you don't have chilli oil, melt a knob of butter in a pan with a pinch of pul biber or dried chilli flakes.","The yoghurt can be mixed with garlic up to 30 minutes ahead; keep it at room temperature.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Mix the yoghurt with the chopped garlic and a pinch of salt. Divide between two shallow bowls and set aside."},{"text":"Fill a saucepan with water, add a splash of white vinegar, and bring to a gentle simmer until tiny bubbles rise from the base, but the water is not at a rolling boil."},{"text":"Crack an egg into a small cup, then slide it into the simmering water. Repeat with the remaining eggs, spacing them out. Poach for about 3 minutes, until the whites are just set but the yolks are still soft."},{"text":"Using a slotted spoon, lift each egg out of the water and place on top of the yoghurt in the bowls."},{"text":"Warm the chilli oil gently in a small pan, just until fragrant, don't let it smoke. Drizzle over the eggs and yoghurt."},{"text":"Sprinkle the sumac and pul biber over the top. Serve straight away while everything is still warm."}],"id":"9579de64-924a-48cc-8470-0f454e9a3f86"},{"notes":["Make the sauce up to a day ahead and reheat gently.","You can roast and peel the chillies an hour before you fry them; keep them in a covered container at room temperature.","Fresh mozzarella is the closest you'll find to Oaxaca at Coles; if you can get to a Latin American grocer in Marrickville, grab the real thing.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Make the sauce first: put the tinned tomatoes, onion and garlic in a pot. Bring to a simmer and cook for 15 minutes until the tomato has broken down and the onion is soft. Blend until smooth (or blitz with a hand blender). Season with salt. Set aside."},{"text":"Roast the poblanos directly over a gas flame, turning often with tongs, until the skin is blackened all over, about 5 minutes. If you don't have gas, put them under a hot grill. Place in a plastic bag for 5 minutes to steam, the skin will come off easier."},{"text":"Peel off the blackened skin under cold running water, gently rubbing with your fingers. Make a slit down one side and carefully remove the seeds and white membrane, keeping the pepper whole."},{"text":"Insert a baton of mozzarella into each pepper. Be gentle, they tear easily. Lay on a plate and let rest."},{"text":"Beat the eggs in a bowl until pale. Spread the flour on a plate. Heat about 5 cm of oil in a deep frying pan to 170°C."},{"text":"Working one at a time, coat each pepper in flour, shaking off excess, then dip in beaten egg to coat completely. Carefully slide into the hot oil."},{"text":"Fry for 2 to 3 minutes each side until golden brown, turning gently. You want the outside crispy and the cheese melting inside. Drain on paper towel."},{"text":"Pour the tomato sauce into a serving dish. Place the fried chillies on top, or serve the sauce on the side. Eat while the cheese is still hot."}],"id":"fe7377d1-12f0-49c3-aa78-de0350450c9c"},{"notes":["The salad is best eaten immediately while the papaya is still crisp. Don't make it ahead.","Adjust the chilli to your heat level, start with 1 or 2 birds eyes if you're not used to heat, then add more.","A proper pestle and mortar is key here; don't use a food processor, which will break down the vegetables too much."],"steps":[{"text":"Pound the chillies and garlic in a mortar until bruised and fragrant, about 1 minute."},{"text":"Add the long beans and tomatoes, gently bruise them, about 30 seconds, don't crush them to mush."},{"text":"Add the papaya and gently pound and toss everything together, crushing and mixing, about 2 minutes. The papaya should start to release juice."},{"text":"Add the lime juice, fish sauce and palm sugar. Toss everything well, tasting as you go."},{"text":"Transfer to a plate, top with crushed peanuts, and serve right away while it's still crisp."}],"id":"a6329102-cda1-4554-aaa3-66daf91e08e9"},{"notes":["Serve with steamed white or jasmine rice to soak up the broth.","You can swap the white fish for any firm white fish you have – barramundi is classic, but flathead and snapper work just as well.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Bring the water and coconut milk to a gentle simmer in a large pot or deep pan over medium heat, until small bubbles form around the edge and the liquid is steaming."},{"text":"Add the ginger slices and turmeric, stirring well. Let it bubble gently for 3 minutes until fragrant."},{"text":"Add the fish pieces and the white parts of the spring onion. Return to a simmer and cook for 8–10 minutes, stirring occasionally, until the fish is cooked through and flakes easily."},{"text":"Stir in the fish sauce and taste. Add salt if needed – go easy, as the fish sauce brings plenty of salt already."},{"text":"Add the green parts of the spring onion and cook for 1 minute more until just wilted."},{"text":"Ladle into bowls and serve hot with steamed white rice to soak up the silky broth."}],"id":"b12a1ca7-47a1-42f5-8edf-61aa66cd30ba"},{"steps":[{"text":"Pat the drained chickpeas dry with a clean tea towel. This removes excess moisture so they'll bind better and fry crisper."},{"text":"Add the chickpeas, onion, garlic, parsley, coriander, spring onions, green chilli, cumin, ground coriander and cayenne to a food processor. Pulse until the mixture is combined but still coarse, not smooth like a paste. It should hold together when squeezed but still have some texture."},{"text":"Transfer to a bowl, stir through the flour, and season with salt and pepper. Refrigerate for at least 2 hours. Cold mixture holds together better when you fry."},{"text":"Pour about 8 cm of neutral oil into a deep heavy-based pan and heat to 170°C. If you don't have a thermometer, drop a small piece of bread in, it should sizzle gently and turn golden in about 30 seconds."},{"text":"Wet your hands lightly to stop the mixture sticking. Shape the mixture into 20 balls about the size of a walnut, then gently flatten each one slightly. Work quickly so they stay cold."},{"text":"Carefully lower the falafel into the hot oil in small batches, don't crowd the pan or the temperature will drop and they'll absorb oil instead of crisping. Fry for 3–4 minutes until deep golden all over, turning halfway. They should be golden outside and cooked through inside."},{"text":"Drain on paper towels and serve warm in flatbread with tahini sauce, fresh tomatoes and coriander. Eat them straightaway while they're still crisp."}],"id":"a6429273-3259-4d2c-b446-569d27357795"},{"notes":["If you can't find fresh lemongrass or galangal, use 1 tbsp lemongrass paste and ½ tsp ground galangal instead.","This works just as well with any firm white fish cut into chunks, cook for 2–3 minutes until opaque.","Food safety: Cook prawns and other crustaceans until the shells turn pink and the flesh is opaque and firm."],"id":"5019533b-1f70-46b0-a6ad-4244fffb836b"},{"notes":["This feeds a crowd and tastes even better the next day. Cool and refrigerate; reheat gently in a low oven.","No camp oven? Works just as well in a covered Dutch oven in the oven at home.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Combine wattleseed, bush tomato, native pepper, salt and black pepper in a small bowl. Rub all over the brisket, working it into the meat, and let sit for 10 minutes."},{"text":"Heat oil in a heavy camp oven or large, heavy-bottomed oven-safe pot over medium-high heat. Sear the brisket on both sides until well browned, about 4 minutes each side. Remove and set aside."},{"text":"Add onion and garlic to the pot and cook, stirring, until soft, about 3 minutes. Pour in stock and red wine, scraping up the browned bits from the bottom."},{"text":"Return the brisket to the pot, fat-side up. Add bay leaves and thyme. Season with salt and pepper. Bring to a simmer until small bubbles break the surface of the liquid steadily."},{"text":"Cover tightly and transfer to a 140°C oven (or set camp oven on low coals). Cook for 5 to 6 hours, turning the brisket halfway through, until the meat is so tender it falls apart with a fork."},{"text":"Remove from the oven and let rest for 15 minutes. Skim any excess fat from the liquid. Slice the brisket or pull it apart, and serve with the pan juices."}],"id":"7a1829a6-ef1a-4fca-bc8f-df775aa7dc1b"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;